[
  {
    "id": "two-sum",
    "title": "Two Sum",
    "difficulty": "Easy",
    "companies": [
      "Amazon",
      "Google"
    ],
    "revision": null,
    "hiddenCount": 0,
    "topic": "Hash maps",
    "description": "Return the zero-based indices of two distinct elements whose sum is target. Exactly one valid pair exists. The same array position cannot be used twice, even when target is twice its value. Equal numbers at different indices are allowed. Return the two indices in either order; returning the values themselves does not satisfy the contract.",
    "constraints": "2 ≤ nums.length ≤ 10,000. Values and target are between −1,000,000 and 1,000,000.",
    "starter": "import java.util.*;\n\nclass Solution {\n    public int[] twoSum(int[] nums, int target) {\n        // Think about the pattern, then make it yours.\n        throw new UnsupportedOperationException(\"Implement your solution\");\n    }\n}\n",
    "method": "twoSum",
    "params": [
      {
        "name": "nums",
        "type": "int[]"
      },
      {
        "name": "target",
        "type": "int"
      }
    ],
    "returns": "int[]",
    "normalize": "sort-int",
    "tests": [
      {
        "args": [
          [
            2,
            7,
            11,
            15
          ],
          9
        ],
        "expected": [
          0,
          1
        ],
        "label": "A friendly first pair"
      },
      {
        "args": [
          [
            3,
            2,
            4
          ],
          6
        ],
        "expected": [
          1,
          2
        ],
        "label": "Look beyond the first value"
      },
      {
        "args": [
          [
            3,
            3
          ],
          6
        ],
        "expected": [
          0,
          1
        ],
        "label": "Equal values, different indices"
      },
      {
        "args": [
          [
            -3,
            4,
            3,
            90
          ],
          0
        ],
        "expected": [
          0,
          2
        ],
        "label": "Negative numbers"
      },
      {
        "args": [
          [
            0,
            4,
            3,
            0
          ],
          0
        ],
        "expected": [
          0,
          3
        ],
        "label": "Zero is a value too"
      }
    ],
    "examples": [
      {
        "args": [
          [
            2,
            7,
            11,
            15
          ],
          9
        ],
        "expected": [
          0,
          1
        ],
        "label": "A friendly first pair"
      },
      {
        "args": [
          [
            3,
            2,
            4
          ],
          6
        ],
        "expected": [
          1,
          2
        ],
        "label": "Look beyond the first value"
      }
    ]
  },
  {
    "id": "contains-duplicate",
    "title": "Contains Duplicate",
    "difficulty": "Easy",
    "companies": [
      "Amazon"
    ],
    "revision": null,
    "hiddenCount": 0,
    "topic": "Hash maps",
    "description": "Determine whether any integer appears at least twice in nums. Compare values, not positions. Return true as soon as a repeated value is found, and false if all values are distinct. Negative numbers and zero are ordinary values. An empty array or an array with one element has no duplicate. You do not need to report which value repeats.",
    "constraints": "0 ≤ nums.length ≤ 10,000. Negative values are allowed.",
    "starter": "import java.util.*;\n\nclass Solution {\n    public boolean containsDuplicate(int[] nums) {\n        // Think about the pattern, then make it yours.\n        throw new UnsupportedOperationException(\"Implement your solution\");\n    }\n}\n",
    "method": "containsDuplicate",
    "params": [
      {
        "name": "nums",
        "type": "int[]"
      }
    ],
    "returns": "boolean",
    "normalize": "",
    "tests": [
      {
        "args": [
          [
            1,
            2,
            3,
            1
          ]
        ],
        "expected": true,
        "label": "A repeated visitor"
      },
      {
        "args": [
          [
            1,
            2,
            3,
            4
          ]
        ],
        "expected": false,
        "label": "All unique"
      },
      {
        "args": [
          []
        ],
        "expected": false,
        "label": "Empty input"
      },
      {
        "args": [
          [
            -1,
            -1
          ]
        ],
        "expected": true,
        "label": "Negative duplicate"
      },
      {
        "args": [
          [
            0
          ]
        ],
        "expected": false,
        "label": "One value"
      }
    ],
    "examples": [
      {
        "args": [
          [
            1,
            2,
            3,
            1
          ]
        ],
        "expected": true,
        "label": "A repeated visitor"
      },
      {
        "args": [
          [
            1,
            2,
            3,
            4
          ]
        ],
        "expected": false,
        "label": "All unique"
      }
    ]
  },
  {
    "id": "valid-anagram",
    "title": "Valid Anagram",
    "difficulty": "Easy",
    "companies": [
      "Amazon",
      "Apple"
    ],
    "revision": null,
    "hiddenCount": 0,
    "topic": "Strings",
    "description": "Decide whether strings s and t contain exactly the same letters with the same frequencies. Rearranging letters is allowed; adding or removing a letter is not. Matching only the set of distinct letters is insufficient because repeated letters matter. The inputs contain lowercase English letters. Two empty strings are anagrams, and different-length strings cannot be anagrams.",
    "constraints": "Only lowercase English letters. 0 ≤ string length ≤ 10,000.",
    "starter": "import java.util.*;\n\nclass Solution {\n    public boolean isAnagram(String s, String t) {\n        // Think about the pattern, then make it yours.\n        throw new UnsupportedOperationException(\"Implement your solution\");\n    }\n}\n",
    "method": "isAnagram",
    "params": [
      {
        "name": "s",
        "type": "String"
      },
      {
        "name": "t",
        "type": "String"
      }
    ],
    "returns": "boolean",
    "normalize": "",
    "tests": [
      {
        "args": [
          "listen",
          "silent"
        ],
        "expected": true,
        "label": "Same letters, new order"
      },
      {
        "args": [
          "rat",
          "car"
        ],
        "expected": false,
        "label": "Different letters"
      },
      {
        "args": [
          "aacc",
          "ccac"
        ],
        "expected": false,
        "label": "Counts matter"
      },
      {
        "args": [
          "",
          ""
        ],
        "expected": true,
        "label": "Empty pair"
      },
      {
        "args": [
          "a",
          "aa"
        ],
        "expected": false,
        "label": "Length mismatch"
      }
    ],
    "examples": [
      {
        "args": [
          "listen",
          "silent"
        ],
        "expected": true,
        "label": "Same letters, new order"
      },
      {
        "args": [
          "rat",
          "car"
        ],
        "expected": false,
        "label": "Different letters"
      }
    ]
  },
