    "hiddenCount": 0,
    "topic": "Binary search",
    "description": "Find target in the strictly increasing sorted array nums. Return its zero-based index if present, or -1 if it is absent. The ordering is part of the input contract, so no sorting is required. Handle an empty search interval without accessing an invalid index. Your algorithm should halve the search interval at each step and run in logarithmic time.",
    "constraints": "0 ≤ nums.length ≤ 10,000. The array is sorted in increasing order.",
    "starter": "import java.util.*;\n\nclass Solution {\n    public int search(int[] nums, int target) {\n        // Think about the pattern, then make it yours.\n        throw new UnsupportedOperationException(\"Implement your solution\");\n    }\n}\n",
    "method": "search",
    "params": [
      {
        "name": "nums",
        "type": "int[]"
      },
      {
        "name": "target",
        "type": "int"
      }
    ],
    "returns": "int",
    "normalize": "",
    "tests": [
      {
        "args": [
          [
            -1,
            0,
            3,
            5,
            9,
            12
          ],
          9
        ],
        "expected": 4,
        "label": "In the right half"
      },
      {
        "args": [
          [
            -1,
            0,
            3,
            5,
            9,
            12
          ],
          2
        ],
        "expected": -1,
        "label": "Missing target"
      },
      {
        "args": [
          [
            5
          ],
          5
        ],
        "expected": 0,
        "label": "A single match"
      },
      {
        "args": [
          [],
          3
        ],
        "expected": -1,
        "label": "Empty search"
      },
      {
        "args": [
          [
            1,
            3,
            5
          ],
          1
        ],
        "expected": 0,
        "label": "Left boundary"
      }
    ],
    "examples": [
      {
        "args": [
          [
            -1,
            0,
            3,
            5,
            9,
            12
          ],
          9
        ],
        "expected": 4,
        "label": "In the right half"
      },
      {
        "args": [
          [
            -1,
            0,
            3,
            5,
            9,
            12
          ],
          2
        ],
        "expected": -1,
        "label": "Missing target"
      }
    ]
  },
