            3,
            5
          ],
          3
        ],
        "expected": 1,
        "label": "First duplicate"
      },
      {
        "args": [
          [
            1,
            3,
            5
          ],
          4
        ],
        "expected": 2,
        "label": "Between values"
      }
    ]
