      {
        "args": [
          [
            0,
            0
          ]
        ],
        "expected": [
          0,
          0
        ],
        "label": "Repeated zero"
      }
    ],
    "examples": [
      {
        "args": [
          [
            -4,
            -1,
            0,
            3,
            10
          ]
        ],
