  {
    "id": "valid-palindrome",
    "title": "Valid Palindrome",
    "difficulty": "Easy",
    "companies": [
      "Amazon",
      "Apple"
    ],
    "revision": null,
    "hiddenCount": 0,
    "topic": "Two pointers",
    "description": "Check whether s reads the same forward and backward after ignoring non-alphanumeric characters and letter case. For this exercise, alphanumeric means ASCII letters a–z or A–Z and digits 0–9. Spaces and punctuation do not participate in comparisons. A string with no remaining characters is a palindrome. You can compare from both ends without constructing a cleaned copy.",
    "constraints": "0 ≤ s.length ≤ 10,000. Input contains ASCII characters only. An empty normalized string is a palindrome.",
    "starter": "import java.util.*;\n\nclass Solution {\n    public boolean isPalindrome(String s) {\n        // Think about the pattern, then make it yours.\n        throw new UnsupportedOperationException(\"Implement your solution\");\n    }\n}\n",
    "method": "isPalindrome",
    "params": [
      {
        "name": "s",
        "type": "String"
      }
    ],
    "returns": "boolean",
    "normalize": "",
    "tests": [
      {
        "args": [
          "A man, a plan, a canal: Panama"
        ],
        "expected": true,
        "label": "Ignore punctuation"
      },
      {
        "args": [
          "race a car"
        ],
        "expected": false,
        "label": "Different middle"
      },
      {
        "args": [
          " "
        ],
        "expected": true,
        "label": "No letters"
      },
      {
        "args": [
          "0P"
        ],
        "expected": false,
        "label": "Digits count"
      },
      {
        "args": [
          "abba"
        ],
        "expected": true,
        "label": "A mirror"
      }
    ],
    "examples": [
      {
        "args": [
          "A man, a plan, a canal: Panama"
        ],
        "expected": true,
        "label": "Ignore punctuation"
      },
      {
        "args": [
          "race a car"
        ],
        "expected": false,
        "label": "Different middle"
      }
    ]
  },
