    "difficulty": "Easy",
    "companies": [
      "Apple",
      "Google"
    ],
    "revision": null,
    "hiddenCount": 0,
    "topic": "Two pointers",
    "description": "Move every zero in nums to the end while preserving the relative order of all nonzero values. Perform the rearrangement in the original array. Unlike a void-returning version of this exercise, this platform also requires you to return the modified array so the judge can compare it. Preserve the length and every value; do not simply remove zero entries. Empty and all-zero arrays should remain valid.",
    "constraints": "0 ≤ nums.length ≤ 10,000. Preserve the relative order of nonzero elements.",
    "starter": "import java.util.*;\n\nclass Solution {\n    public int[] moveZeroes(int[] nums) {\n        // Think about the pattern, then make it yours.\n        throw new UnsupportedOperationException(\"Implement your solution\");\n    }\n}\n",
    "method": "moveZeroes",
    "params": [
      {
        "name": "nums",
        "type": "int[]"
      }
    ],
    "returns": "int[]",
    "normalize": "",
    "tests": [
      {
        "args": [
          [
            0,
            1,
            0,
            3,
            12
          ]
        ],
        "expected": [
          1,
          3,
          12,
          0,
          0
        ],
        "label": "Lift the nonzero values"
      },
      {
        "args": [
          [
            0
          ]
        ],
        "expected": [
          0
        ],
        "label": "Only zero"
      },
      {
        "args": [
          []
        ],
        "expected": [],
        "label": "Empty array"
      },
      {
        "args": [
          [
            1,
            2
          ]
        ],
        "expected": [
          1,
          2
        ],
        "label": "Already in place"
      },
      {
        "args": [
          [
            0,
            0,
            1
          ]
        ],
        "expected": [
          1,
          0,
          0
        ],
        "label": "Leading zeroes"
      }
    ],
    "examples": [
      {
        "args": [
          [
            0,
            1,
            0,
            3,
            12
          ]
        ],
        "expected": [
          1,
          3,
          12,
          0,
          0
        ],
        "label": "Lift the nonzero values"
      },
      {
        "args": [
          [
            0
          ]
        ],
        "expected": [
          0
        ],
        "label": "Only zero"
      }
    ]
  },
