  document.head.append(loader);
});

const channel = "bytequest-java";
const send = data => parent.postMessage({channel,...data}, location.origin);
let Runner;
let running = false;
try {
  if (typeof cheerpjInit !== "function") throw new Error("The Java runtime CDN is unavailable. Check your connection and try again.");
  send({type:"status",message:"Loading the browser JDK. The first launch can take a minute."});
  await cheerpjInit({version:17,status:"none",javaProperties:["java.io.tmpdir=/files"]});
  const jar = "/app" + new URL("java-runner.jar", location.href).pathname;
  const lib = await cheerpjRunLibrary(jar);
  Runner = await lib.quest.JavaRunner;
  // Warm javac too: loading the JVM alone leaves the compiler's first-use download on Run.
  send({type:"status",message:"Preparing the Java compiler in the background…"});
  const warm=JSON.parse(await Runner.run("class Solution { public int warmup() { return 0; } }",'check("Compiler warm-up", () -> new Solution().warmup(), 0);'));
  if(warm.status!=="ok"||!warm.cases.every(c=>c.passed))throw new Error("Compiler warm-up failed.");
  send({id:"boot",type:"ready",result:true});
} catch (error) {
  send({id:"boot",type:"error",message:"Java could not start: " + String(error.message || error)});
}
addEventListener("message", async event => {
  if (event.source !== parent || event.origin !== location.origin || event.data?.channel !== channel || event.data.type !== "run") return;
  const {id,source,tests} = event.data;
  if (!Runner || running) { send({id,type:"error",message:"The Java runtime is busy or not ready."}); return; }
  running = true;
  try { send({id,type:"result",result:JSON.parse(await Runner.run(source,tests))}); }
  catch (error) { send({id,type:"error",message:String(error.message || error)}); }
  finally { running = false; }
});

export function mountAccountDeletion(cloud){
 const dialog=document.createElement('dialog');dialog.className='social-dialog delete-account-dialog';dialog.setAttribute('aria-labelledby','deleteAccountTitle');dialog.innerHTML='<div class="dialog-heading"><h2 id="deleteAccountTitle">Delete your ByteQuest account?</h2><button id="cancelAccountDeletion" aria-label="Close account deletion">×</button></div><p>Your profile, progress, notes, drafts, photo, follows, chat messages and submitted solutions will be permanently removed. Unpublished problems you created will be deleted. Published problems stay in the community library without your account attribution.</p><p>Your Google account is kept. Confirm your identity with Google before removal.</p><label class="delete-confirm-label">Type DELETE to confirm<input id="deleteAccountConfirmation" autocomplete="off" spellcheck="false" placeholder="DELETE"></label><p id="deleteAccountStatus" role="status"></p><div class="delete-actions"><button id="cancelDeletion" class="button secondary">Cancel</button><button id="confirmAccountDeletion" class="danger-button" disabled>Verify and delete account</button></div>';document.body.append(dialog);
 const $=id=>document.getElementById(id),confirm=$('confirmAccountDeletion'),field=$('deleteAccountConfirmation');let busy=false;
 const menuButton=document.createElement('button');menuButton.type='button';menuButton.hidden=!cloud.user;menuButton.className='delete-menu-button';menuButton.textContent='Delete account';$('menuAccountSlot')?.append(menuButton);
 function open(){field.value='';confirm.disabled=true;$('deleteAccountStatus').textContent=cloud.user?'':'Sign in to manage your account.';confirm.textContent=cloud.deletionPending?'Retry deletion':'Verify and delete account';if(!dialog.open)dialog.showModal();}
 menuButton.onclick=open;if($('deleteAccountButton'))$('deleteAccountButton').onclick=open;
 field.oninput=()=>{confirm.disabled=busy||!cloud.user||field.value!=='DELETE';};const close=()=>{if(!busy)dialog.close();};$('cancelAccountDeletion').onclick=close;$('cancelDeletion').onclick=close;dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
 confirm.onclick=async()=>{if(field.value!=='DELETE'||busy||!cloud.user)return;busy=true;confirm.disabled=true;$('deleteAccountStatus').textContent=cloud.deletionPending?'Finishing account removal…':'Verify your Google identity to continue…';try{await cloud.deleteAccount();dialog.close();location.replace('./index.html?account=deleted#map');}catch(e){$('deleteAccountStatus').textContent=e.message;confirm.textContent=cloud.deletionPending?'Retry deletion':'Verify and delete account';}finally{busy=false;confirm.disabled=field.value!=='DELETE';}};
 return{open};
}

/* Precise activity comparison + published-catalog topic growth. */
.community-page #profileAnalytics{margin-top:19px}
.community-page #profileAnalytics .dashboard-chart{
 padding:22px 24px 19px;
 border:1px solid var(--border);
 border-radius:13px;
 box-shadow:none!important;
 background:var(--surface)!important;
 background-image:none!important;
}
.community-page #profileAnalytics .chart-heading{
 display:flex;align-items:center;justify-content:space-between;
 flex-direction:row;flex-wrap:wrap;gap:14px;
 margin-bottom:14px;
}
.community-page #profileAnalytics .chart-heading h2{
 margin:0 0 5px;
 font:650 20px/1.3 var(--font-sans)!important;
 letter-spacing:-.025em;
 color:var(--text);
}
.community-page #profileAnalytics .chart-heading p{
 margin:0!important;font:400 11px/1.5 var(--font-sans)!important;
 color:var(--muted)!important;
}
.community-page #profileAnalytics .chart-filters{
 display:flex;flex:0 1 auto;align-items:center;
 gap:7px;flex-wrap:wrap;width:auto;
}
.community-page #profileAnalytics .chart-filters :is(select,input){
 min-height:35px;height:35px;
 border:1px solid var(--border);border-radius:7px;
 background:var(--surface-2)!important;
 padding:7px 10px;
 font:500 10px/1.4 var(--font-sans);
 color:var(--text);
}
.community-page #profileAnalytics .chart-filters :is(select,input):focus-visible,
.community-page #profileAnalytics .topic-progress-toggle:focus-visible{
 outline:2px solid var(--accent);outline-offset:2px;
}
.community-page #profileAnalytics .chart-filters #graphMeasure{min-width:116px}
.community-page #profileAnalytics .chart-filters #graphTopic{max-width:160px}
.community-page #profileAnalytics .graph-scroll{
 position:relative;min-height:190px;
 padding:8px 0 0!important;
 overflow-x:auto;scrollbar-width:thin;
 background:transparent!important;
}
.community-page #profileAnalytics #frequencyChart{
 display:block;width:100%;min-width:520px;
 max-height:260px;overflow:visible;
}
.community-page #profileAnalytics #frequencyChart text{
 font:10px var(--font-mono);
 fill:var(--muted);
}
.community-page #profileAnalytics .graph-curve{
 animation:none!important;
 stroke-dasharray:none!important;
 stroke-dashoffset:0!important;
 transition:none!important;
}
.community-page #profileAnalytics .graph-precise-line{
 stroke-linecap:round;
 stroke-linejoin:round;
}
.community-page #profileAnalytics #frequencyChart circle{stroke:var(--surface);stroke-width:1}
.community-page #profileAnalytics .graph-no-data{font:600 13px var(--font-sans)!important}
.community-page #profileAnalytics .graph-legend{
 display:flex;align-items:center;gap:8px 15px;
 margin:0 0 12px;
 max-height:90px;overflow:auto;
}
.community-page #profileAnalytics .comparison-controls{margin-top:15px}
.community-page #profileAnalytics .chart-footnote{
 font:400 10px/1.6 var(--font-sans)!important;
 color:var(--muted)!important;
 margin-top:10px;
}
/* Readable topic completion, relative to distinct published problems. */
.community-page #profileAnalytics .topic-summary{
 display:grid;grid-template-columns:minmax(0,200px) minmax(0,1fr);
 gap:22px;
 align-items:start;
 margin:17px 0!important;
 padding:23px 24px!important;
 border:1px solid var(--border);
 border-radius:13px;
 background:var(--surface)!important;
 background-image:none!important;
 box-shadow:none!important;
}
.community-page #profileAnalytics .topic-summary h2{
 margin:0 0 6px;
 font:650 19px/1.35 var(--font-sans)!important;
 letter-spacing:-.025em;
 color:var(--text);
}
.community-page #profileAnalytics .topic-summary p{
 margin:0;
 font:400 11px/1.6 var(--font-sans)!important;
 color:var(--muted)!important;
}
.community-page #profileAnalytics #topicBreakdown{
 width:100%;max-width:690px;
 min-width:0;display:flex;
 flex-direction:column;gap:12px;
}
.community-page #profileAnalytics .topic-progress-caption{
 font-size:10px!important;line-height:1.5;
 color:var(--muted)!important;
 margin:0 0 2px!important;
}
.community-page #profileAnalytics .topic-progress-row{
 min-width:0;display:flex;
 flex-direction:column;gap:6px;
 padding:0 0 9px;
 border-bottom:1px solid var(--border);
}
.community-page #profileAnalytics .topic-progress-row:last-of-type{border-bottom:0}
.community-page #profileAnalytics .topic-progress-heading{
 display:flex;align-items:center;
 justify-content:space-between;gap:12px;
 font:500 11px/1.5 var(--font-sans);
}
.community-page #profileAnalytics .topic-progress-heading span{
 min-width:0;overflow:hidden;
