}
.community-page #profileAnalytics .topic-progress-toggle:hover{
 color:var(--accent);border-color:var(--accent);
}
.community-page #profileAnalytics .topic-unavailable{margin:4px 0;color:var(--muted)}
@media(max-width:1050px){
 .community-page #profileAnalytics .chart-heading{align-items:flex-start}
 .community-page #profileAnalytics .chart-filters{width:100%}
 .community-page #profileAnalytics .topic-summary{grid-template-columns:1fr;gap:17px}
 .community-page #profileAnalytics #topicBreakdown{max-width:none}
}
@media(max-width:600px){
 .community-page #profileAnalytics .dashboard-chart{padding:16px 13px}
 .community-page #profileAnalytics .chart-heading h2{font-size:18px!important}
