 .community-page #profileAnalytics .chart-filters :is(select,input){
  flex:1 1 120px;min-width:95px;max-width:none;
 }
 .community-page #profileAnalytics #frequencyChart{min-width:480px}
 .community-page #profileAnalytics .topic-summary{padding:18px 15px!important}
 .community-page #profileAnalytics .topic-summary h2{font-size:18px!important}
